namespace sv_58d92f5bb3ef477396b1237a7b60d376.Services;

/// <summary>
/// Scoped service that polls for low-stock alerts and notifies all subscribers.
/// Each circuit (user) gets its own instance, ensuring isolation.
/// </summary>
public sealed class InventoryAlertService : IDisposable
{
    private readonly Random _random = new();
    private PeriodicTimer? _timer;
    private CancellationTokenSource? _cts;
    private int _subscriberCount;

    public int CurrentLowStockCount { get; private set; }
    public string? CurrentWarehouseId { get; private set; }

    /// <summary>
    /// Raised when new alert data arrives. Subscribers must wrap
    /// StateHasChanged in InvokeAsync since this fires from a background thread.
    /// </summary>
    public event Action? OnChange;

    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        // Simulates a database query
        return Task.FromResult(_random.Next(0, 16));
    }

    public void SetWarehouse(string warehouseId)
    {
        CurrentWarehouseId = warehouseId;
    }

    /// <summary>
    /// Call when a component that needs polling becomes active.
    /// Starts the timer on the first subscriber.
    /// </summary>
    public void Subscribe()
    {
        _subscriberCount++;
        if (_subscriberCount == 1)
        {
            StartPolling();
        }
    }

    /// <summary>
    /// Call when a component that needs polling is disposed.
    /// Stops the timer when no subscribers remain.
    /// </summary>
    public void Unsubscribe()
    {
        _subscriberCount = Math.Max(0, _subscriberCount - 1);
        if (_subscriberCount == 0)
        {
            StopPolling();
        }
    }

    private void StartPolling()
    {
        _cts = new CancellationTokenSource();
        _timer = new PeriodicTimer(TimeSpan.FromSeconds(10));
        _ = PollLoopAsync(_cts.Token);
    }

    private void StopPolling()
    {
        _cts?.Cancel();
        _timer?.Dispose();
        _timer = null;
        _cts?.Dispose();
        _cts = null;
    }

    private async Task PollLoopAsync(CancellationToken ct)
    {
        // Fire immediately on first subscribe
        await FetchAndNotifyAsync();

        while (!ct.IsCancellationRequested)
        {
            try
            {
                if (_timer is not null && await _timer.WaitForNextTickAsync(ct))
                {
                    await FetchAndNotifyAsync();
                }
            }
            catch (OperationCanceledException)
            {
                break;
            }
        }
    }

    private async Task FetchAndNotifyAsync()
    {
        if (CurrentWarehouseId is null) return;
        CurrentLowStockCount = await GetLowStockCountAsync(CurrentWarehouseId);
        OnChange?.Invoke();
    }

    public void Dispose()
    {
        StopPolling();
    }
}

