toolArgs.file_text:
@page "/dashboard"
@rendermode InteractiveServer
@inject InventoryAlertService AlertService
@implements IDisposable
@using sv_58d92f5bb3ef477396b1237a7b60d376.Services

<PageTitle>Dashboard</PageTitle>

<h1>Warehouse Dashboard</h1>

<div class="card mt-4" style="max-width: 400px;">
    <div class="card-body">
        <h5 class="card-title">
            Low-Stock Alerts
            <span class="badge bg-warning text-dark fs-6">@AlertService.CurrentLowStockCount</span>
        </h5>
        <p class="card-text text-muted">
            Monitoring <strong>@(_warehouseName ?? "...")</strong> &mdash;
            refreshes every 10 seconds.
        </p>
    </div>
</div>

@code {
    private Action? _handler;
    private string? _warehouseName;

    [CascadingParameter]
    private WarehouseInfo? Warehouse { get; set; }

    protected override void OnInitialized()
    {
        _handler = () => InvokeAsync(StateHasChanged);
        AlertService.OnChange += _handler;
        AlertService.Subscribe();
    }

    protected override void OnParametersSet()
    {
        if (Warehouse is not null)
        {
            _warehouseName = Warehouse.Name;
            AlertService.SetWarehouse(Warehouse.Id);
        }
    }

    public void Dispose()
    {
        AlertService.Unsubscribe();
        if (_handler is not null)
            AlertService.OnChange -= _handler;
    }
}

